bool FileAccessPackedByteArray::store_buffer(const uint8_t *src, uint64_t p_length) {
	if (!p_length) {
		return true;
	}

	ERR_FAIL_NULL_V(src, false);

	uint64_t left = data.size() - pos;
	uint64_t write = MIN(p_length, left);

	memcpy(data.ptrw() + pos, src, write);
	pos += write;

	ERR_FAIL_COND_V_MSG(write < p_length, false, "Writing less data than requested.");

	return true;
}
